import { Router, type Response } from 'express';
import { createWidgetSettingsSchema, updateWidgetSettingsSchema } from '@supportflow/shared';
import type { Env } from '../env.js';
import { ApiError } from '../errors.js';
import { getUserSupabase } from '../lib/supabase.js';
import { validateBody } from '../middleware/validate.js';
import type { AuthedRequest } from '../middleware/auth.js';

/**
 * Admin widget-settings management (Phase 2 frontend).
 * One row per workspace (workspace_id UNIQUE in the schema). The public key
 * is generated by the database and is never changeable through this router:
 * it is not part of either schema, and update validation is strict, so a
 * public_key / workspace_id in the body is rejected with 400.
 */
export function widgetSettingsRouter(env: Env) {
  const router = Router({ mergeParams: true });

  // GET / — 404 when the workspace has no widget settings yet.
  router.get('/', async (req: AuthedRequest, res: Response, next) => {
    try {
      const workspaceId = req.params.workspaceId as string;
      const supabase = getUserSupabase(env, req.token!);
      const { data, error } = await supabase
        .from('widget_settings')
        .select('*')
        .eq('workspace_id', workspaceId)
        .maybeSingle();
      if (error) throw new ApiError(500, 'Failed to load widget settings');
      if (!data) throw new ApiError(404, 'Widget settings not found');
      return res.json({ widget_settings: data });
    } catch (e) {
      return next(e);
    }
  });

  // POST / — create once. A second create is 409 (use PATCH to update).
  router.post(
    '/',
    validateBody(createWidgetSettingsSchema),
    async (req: AuthedRequest, res: Response, next) => {
      try {
        const workspaceId = req.params.workspaceId as string;
        const supabase = getUserSupabase(env, req.token!);
        const { data: existing } = await supabase
          .from('widget_settings')
          .select('id')
          .eq('workspace_id', workspaceId)
          .maybeSingle();
        if (existing) throw new ApiError(409, 'Widget settings already exist for this workspace');
        const { data, error } = await supabase
          .from('widget_settings')
          .insert({
            workspace_id: workspaceId,
            business_name: req.body.business_name ?? 'Support',
            welcome_message: req.body.welcome_message ?? 'Hi! How can we help you today?',
            primary_color: req.body.primary_color ?? '#7C3AED',
            enabled: req.body.enabled ?? true,
            allowed_origins: req.body.allowed_origins ?? [],
          })
          .select()
          .single();
        if (error || !data) throw new ApiError(500, 'Failed to create widget settings');
        return res.status(201).json({ widget_settings: data });
      } catch (e) {
        return next(e);
      }
    },
  );

  // PATCH / — update branding/enabled/origins. Never changes public_key or workspace_id.
  router.patch(
    '/',
    validateBody(updateWidgetSettingsSchema),
    async (req: AuthedRequest, res: Response, next) => {
      try {
        const workspaceId = req.params.workspaceId as string;
        const patch: Record<string, unknown> = {};
        for (const key of ['business_name', 'welcome_message', 'primary_color', 'enabled', 'allowed_origins'] as const) {
          if (req.body[key] !== undefined) patch[key] = req.body[key];
        }
        if (Object.keys(patch).length === 0) {
          throw new ApiError(400, 'No fields to update');
        }
        const supabase = getUserSupabase(env, req.token!);
        const { data, error } = await supabase
          .from('widget_settings')
          .update(patch)
          .eq('workspace_id', workspaceId)
          .select()
          .single();
        if (error) {
          if ((error as { code?: string }).code === 'PGRST116') {
            throw new ApiError(404, 'Widget settings not found');
          }
          throw new ApiError(500, 'Failed to update widget settings');
        }
        if (!data) throw new ApiError(404, 'Widget settings not found');
        return res.json({ widget_settings: data });
      } catch (e) {
        return next(e);
      }
    },
  );

  return router;
}
